// Types and pure helpers of the certificates API, shared by server and client
// code. Contract: docs/API_EMISION_VERIFICACION.md.

/** 200 MB, the same limit the backend enforces. */
export const MAX_FILE_BYTES = 200 * 1024 * 1024;

export type Certificate = {
  id: string;
  title: string;
  recipient: string;
  // SHA-256 of the manifest (or of the v1 record), generated by the backend.
  contentHash: string;
  createdAt: string;
  // 1 = issued before file certificates: every field below is null.
  hashVersion: number;
  fileSha256: string | null;
  fileSizeBytes: number | null;
  fileName: string | null;
  satellite: string | null;
  sensor: string | null;
  sceneId: string | null;
  acquiredAt: string | null;
};

/** The metadata declared when issuing, sent in X-SpaceProof-Metadata. */
export type CertificateMetadata = {
  title: string;
  recipient: string;
  satellite: string;
  sensor?: string;
  sceneId?: string;
  // ISO 8601 instant with seconds and zone.
  acquiredAt: string;
  fileName: string;
};

export type Verification = {
  status: "VALID" | "INVALID" | "PENDING" | "UNVERIFIABLE";
  reason:
    | "FILE_MISMATCH"
    | "RECORD_MISMATCH"
    | "NOT_ANCHORED"
    | "ANCHOR_NOT_CONFIGURED"
    | "ANCHOR_UNAVAILABLE"
    | null;
  checks: {
    file: "MATCH" | "MISMATCH" | "NOT_CHECKED";
    record: "MATCH" | "MISMATCH";
    anchor:
      | "ANCHORED"
      | "NOT_ANCHORED"
      | "NOT_CONFIGURED"
      | "UNAVAILABLE"
      | "NOT_CHECKED";
  };
  hashVersion: number;
  storedHash: string;
  computedHash: string;
  file: {
    storedSha256: string;
    receivedSha256: string;
    receivedSizeBytes: number;
  } | null;
  anchoredAt: string | null;
};

// NestJS errors carry `message` as a string or, for validation, a string[].
export function errorMessage(body: unknown, status: number): string {
  const message = (body as { message?: unknown } | null)?.message;
  if (Array.isArray(message)) return message.join(". ");
  if (typeof message === "string") return message;
  return `Error ${status}`;
}

export function formatDate(iso: string): string {
  return new Intl.DateTimeFormat("es-AR", {
    dateStyle: "medium",
    timeStyle: "short",
  }).format(new Date(iso));
}

/** A declared instant, shown in UTC so every reader sees the same value. */
export function formatUtc(iso: string): string {
  return `${new Intl.DateTimeFormat("es-AR", {
    dateStyle: "medium",
    timeStyle: "medium",
    hourCycle: "h23",
    timeZone: "UTC",
  }).format(new Date(iso))} UTC`;
}

export function formatBytes(bytes: number): string {
  if (bytes < 1024) return `${bytes} bytes`;
  const units = ["KB", "MB", "GB"];
  let value = bytes / 1024;
  let unit = 0;
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024;
    unit++;
  }
  const amount = new Intl.NumberFormat("es-AR", {
    maximumFractionDigits: 1,
  }).format(value);
  return `${amount} ${units[unit]}`;
}
